css:
/* castle-design for ircord: the shape tokens of castle.css, and frosted glass over the castle. Colours come from the theme's seeds (light and dark); on the web a rule on html[data-theme="dark"] could switch on the mode, the desktop client reads only the plain root rules. */
:root:root {
  --radius: 10px;
  --radius-large: 16px;
  --font-ui: system-ui, -apple-system, "Segoe UI", Roboto, "Noto Sans", sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}
/* With the castle picture as the background (web client, once chosen) the panels blur it, as the castle apps' glass does. Opacity is left to ircord, which keeps it above the contrast floors it computes from the picture. Rules without a background match nothing. The conversation's blur stays off below 1100 px, where a backdrop-filter would re-parent ircord's fixed members drawer. */
@media (min-width: 1100px) {
  :root[data-theme-background='app'] .chat-main {
    -webkit-backdrop-filter: blur(10px);
    backdrop-filter: blur(10px);
  }
}
@media (min-width: 900px) {
  :root[data-theme-background='app'] .conversation-sidebar {
    -webkit-backdrop-filter: blur(10px);
    backdrop-filter: blur(10px);
  }
}
